{
  "document_kind": "excerpt_note",
  "report_markdown": "ENTWURF\n\n**Auszug:**\nPatient oder Angehöriger äußert starke emotionale Belastung angesichts massiven Blutverlusts und eines Sprungs (möglicher Sturz oder Suizidversuch). Äußert Zweifel an Überlebenschance und fühlt sich schuldig.",
  "facts": [
    {
      "category": "emotionale_wahrnehmung",
      "claim": "Der Sprecher fühlt sich schuldig.",
      "evidence_quotes": [
        "Ich fühle mich so schuldig …"
      ]
    },
    {
      "category": "beschriebenes_ereignis",
      "claim": "Es wird über starkes Bluten berichtet.",
      "evidence_quotes": [
        "Aber er hat wahnsinnig geblutet"
      ]
    },
    {
      "category": "beschriebenes_ereignis",
      "claim": "Ein Sprung wird erwähnt.",
      "evidence_quotes": [
        "dann noch der Sprung?"
      ]
    },
    {
      "category": "prognosefrage",
      "claim": "Der Sprecher fragt, ob die Person überleben wird.",
      "evidence_quotes": [
        "Herr Doktor, wird er überleben?"
      ]
    },
    {
      "category": "prognosewahrnehmung",
      "claim": "Der Sprecher bezweifelt, dass man das Ereignis überleben kann.",
      "evidence_quotes": [
        "Das kann man doch gar nicht überleben. Oder?"
      ]
    }
  ],
  "uncertainties": [
    "Unklar, ob 'er' Patient oder eine andere Person ist.",
    "Unklar, um welche Art des Sprungs es sich handelt (z. B. Sturz, Suizidversuch).",
    "Unklar, ob das Blutungsereignis vor oder nach dem Sprung stattfand.",
    "Unklar, ob medizinische Versorgung bereits erfolgte oder ausstehend ist."
  ]
}
